css:
.fx-msw{width:min(560px,100%);border:1px solid var(--border);border-radius:var(--radius);padding:1.3em;background:var(--surface)}
.fx-msw .g{display:grid;grid-template-columns:repeat(3,1fr);gap:.8em}
.fx-msw button{position:relative;border:0;padding:0;background:none;text-align:left;cursor:pointer;color:var(--text);font:600 .85em var(--font-body)}
.fx-msw .t{display:block;aspect-ratio:1;border-radius:calc(var(--radius)*.7);border:1px solid var(--border);margin-bottom:.4em;transition:transform calc(.2s/var(--speed)),box-shadow calc(.2s/var(--speed))}
.fx-msw button:hover .t{transform:translateY(-3px);box-shadow:0 8px 16px color-mix(in srgb,#000 14%,transparent)}
.fx-msw button[aria-pressed=true] .t{outline:3px solid var(--accent);outline-offset:2px}
.fx-msw button[aria-pressed=true]::after{content:"✓";position:absolute;right:.5em;top:.5em;width:1.6em;height:1.6em;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;font-size:.8em}
.fx-msw .wood{background:repeating-linear-gradient(92deg,color-mix(in srgb,var(--primary) 55%,#e8cfa3) 0 5px,color-mix(in srgb,var(--primary) 70%,#d1b07b) 5px 9px,color-mix(in srgb,var(--primary) 60%,#e8cfa3) 9px 16px)}
.fx-msw .oak{background:repeating-linear-gradient(88deg,color-mix(in srgb,var(--accent) 22%,#f0ddb8) 0 7px,color-mix(in srgb,var(--accent) 30%,#e6cfa0) 7px 11px)}
.fx-msw .wv{background:repeating-linear-gradient(0deg,color-mix(in srgb,var(--secondary) 40%,#fff) 0 3px,color-mix(in srgb,var(--secondary) 55%,#fff) 3px 6px),repeating-linear-gradient(90deg,transparent 0 3px,color-mix(in srgb,#000 8%,transparent) 3px 6px)}
.fx-msw .st{background:radial-gradient(circle at 20% 30%,color-mix(in srgb,var(--text) 14%,#fff) 0 8%,transparent 9%),radial-gradient(circle at 70% 60%,color-mix(in srgb,var(--text) 20%,#fff) 0 6%,transparent 7%),color-mix(in srgb,var(--text) 8%,#f0f0f0)}
.fx-msw .mt{background:linear-gradient(115deg,color-mix(in srgb,var(--secondary) 70%,#555),color-mix(in srgb,var(--secondary) 30%,#fff) 40%,color-mix(in srgb,var(--secondary) 70%,#555) 60%,color-mix(in srgb,var(--secondary) 40%,#fff))}
.fx-msw .lt{background:radial-gradient(circle at 30% 30%,color-mix(in srgb,var(--accent) 45%,#6b3a1f),color-mix(in srgb,var(--accent) 30%,#3a1f10))}
.fx-msw .ft{display:flex;justify-content:space-between;align-items:center;margin-top:1.1em;padding-top:1em;border-top:1px dashed var(--border);font-size:.92em}
.fx-msw .ft button{background:var(--primary);color:var(--on-primary);border-radius:99px;padding:.65em 1.3em;font-weight:700}
.fx-msw .ft button:disabled{opacity:.4;cursor:not-allowed}
@media(prefers-reduced-motion:reduce){.fx-msw .t{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-msw button.is-tap .t{transform:translateY(-3px);box-shadow:0 8px 16px color-mix(in srgb,#000 14%,transparent)}

js:
(function(){var r=document.querySelector('.fx-msw'),bs=r.querySelectorAll('.g button'),c=r.querySelector('#fx-msw-c'),go=r.querySelector('.ft button');
function n(){return r.querySelectorAll('.g [aria-pressed=true]').length}
bs.forEach(function(b){b.onclick=function(){var on=b.getAttribute('aria-pressed')==='true';if(!on&&n()>=4)return;b.setAttribute('aria-pressed',!on);var k=n();c.textContent=k+' of 4 samples'+(k===4?' (full)':'');go.disabled=k===0}})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
